CREATE EXTENSION IF NOT EXISTS pg_trgm;

CREATE TABLE IF NOT EXISTS archive_songs (
    archive_key TEXT PRIMARY KEY,
    archive_song_id BIGINT,
    name TEXT,
    creator TEXT,
    style TEXT,
    date_created DATE,
    avr NUMERIC,
    filename TEXT,
    extension TEXT,
    filesize BIGINT CHECK (filesize >= 0),
    s3_uri TEXT,
    source_path TEXT,
    metadata_source TEXT
);

CREATE INDEX IF NOT EXISTS idx_archive_songs_archive_song_id ON archive_songs (archive_song_id);
CREATE INDEX IF NOT EXISTS idx_archive_songs_name_trgm
    ON archive_songs USING GIN (name gin_trgm_ops);
CREATE INDEX IF NOT EXISTS idx_archive_songs_filename_trgm
    ON archive_songs USING GIN (filename gin_trgm_ops);
CREATE INDEX IF NOT EXISTS idx_archive_songs_creator_trgm
    ON archive_songs USING GIN (creator gin_trgm_ops);
CREATE INDEX IF NOT EXISTS idx_archive_songs_date_created
    ON archive_songs (date_created DESC NULLS LAST, archive_key);

CREATE TABLE IF NOT EXISTS archive_refills (
    archive_key TEXT PRIMARY KEY,
    archive_refill_id BIGINT,
    name TEXT,
    creator TEXT,
    date_created DATE,
    filename TEXT,
    extension TEXT,
    filesize BIGINT CHECK (filesize >= 0),
    s3_uri TEXT,
    source_path TEXT,
    metadata_source TEXT
