CREATE INDEX IF NOT EXISTS idx_archive_refills_archive_refill_id ON archive_refills (archive_refill_id);
CREATE INDEX IF NOT EXISTS idx_archive_refills_name_trgm
    ON archive_refills USING GIN (name gin_trgm_ops);
CREATE INDEX IF NOT EXISTS idx_archive_refills_filename_trgm
    ON archive_refills USING GIN (filename gin_trgm_ops);
CREATE INDEX IF NOT EXISTS idx_archive_refills_creator_trgm
    ON archive_refills USING GIN (creator gin_trgm_ops);
CREATE INDEX IF NOT EXISTS idx_archive_refills_date_created
    ON archive_refills (date_created DESC NULLS LAST, archive_key);

